UPDATE events
SET
    title = #{title},
    description = #{description},
    max_participants = #{maxParticipants}
WHERE id = #{id}
    AND host_user_id = #{hostUserId}
    AND status = 'DRAFT'
    AND deleted_at IS NULL

UPDATE events
    SET status = #{toStatus}
WHERE id = #{id}
    AND host_user_id = #{hostUserId}
    AND status = #{fromStatus}
    AND deleted_at IS NULL
